-- DQ-006: PR Status Domain---- Purpose:-- Validate the observed values of the PR.Status variable-- in the staging layer.---- Expected categories:-- - Positive-- - Negative-- - NULL-- - Not Performed-- - Performed but Not Available-- - Indeterminate---- Expected record counts:-- - Positive = 353-- - Negative = 193-- - NULL = 122-- - Not Performed = 28-- - Performed but Not Available = 5-- - Indeterminate = 4-- - Total records = 705---- This validation does not modify the data.SELECT    "PR.Status",    COUNT(*) AS quantityFROM staging.brca_sample_wideGROUP BY "PR.Status"ORDER BY quantity DESC;